changeSet.sql:
CREATE TABLE IF NOT EXISTS backend.department (
id SERIAL PRIMARY KEY,
name VARCHAR(150) NOT NULL
);

CREATE TABLE IF NOT EXISTS backend.employer (
id SERIAL PRIMARY KEY,
department_id INT NOT NULL REFERENCES backend.department(id),
name VARCHAR(100) NOT NULL,
last_name VARCHAR(100) NOT NULL,
age INT NOT NULL
);

CREATE TABLE IF NOT EXISTS backend.equipment (
id SERIAL PRIMARY KEY,
name VARCHAR(250) NOT NULL,
employer_id INT REFERENCES backend.employer(id),
status VARCHAR(250) NOT NULL,
start_date DATE
);

rollback.sql:
DROP TABLE IF EXISTS backend.equipment CASCADE;
DROP TABLE IF EXISTS backend.employer CASCADE;
DROP TABLE IF EXISTS backend.department CASCADE;
